-- Auto-generated by WezTerm Tab Theme Picker
-- Theme #30: VS Code Modern Dark (Paletas Populares Devs)
-- Style: pills
-- Symbols: {"arrow": "powerline", "inactive": "diamond", "marker": "balls", "prefix": "rocket"}

local M = {}

function M.apply(config, wezterm)
  config.use_fancy_tab_bar = true
  config.tab_bar_at_bottom = true
  config.show_tab_index_in_tab_bar = false
  config.tab_max_width = 36
  config.colors = config.colors or {}
  config.colors.tab_bar = {
    background = '#181818',
    active_tab = { bg_color = '#007acc', fg_color = '#ffffff' },
    inactive_tab = { bg_color = '#af7ac5', fg_color = '#ffffff' },
    inactive_tab_hover = { bg_color = '#4ec9b0', fg_color = '#181818' },
    new_tab = { bg_color = '#181818', fg_color = '#64748b' },
    new_tab_hover = { bg_color = '#007acc', fg_color = '#ffffff' },
  }
  -- The fancy tab bar paints its strip with the window frame colors, not
  -- colors.tab_bar.background; keep them on the theme's bar color.
  if config.use_fancy_tab_bar then
    config.window_frame = config.window_frame or {}
    config.window_frame.active_titlebar_bg = '#181818'
    config.window_frame.inactive_titlebar_bg = '#181818'
  end

  local TAB_TITLE_LEN = 15

  local function format_fixed(text, len)
    len = len or TAB_TITLE_LEN
    local w = wezterm.column_width(text)
    if w > len then
      return wezterm.truncate_right(text, len - 1) .. '…'
    else
      return wezterm.pad_right(text, len)
    end
  end

  local function get_title_info(tab)
    local pane = tab.active_pane
    local index = tab.tab_index + 1
    local cwd_uri = pane.current_working_dir
    local dir = '~'
    if cwd_uri then
      local cwd = cwd_uri.file_path
      dir = cwd:match('([^/]+)/?$') or cwd
    end
    local uv_cmd = (pane.user_vars or {}).cmd or ''
    local fg = pane.foreground_process_name or ''
    local process = uv_cmd ~= '' and uv_cmd or (fg:match('([^/\\]+)$') or '')
    if process == 'bash' or process == 'zsh' or process == 'fish' or process == 'tmux' or process == 'wezterm' then
      process = ''
    end
    local label = dir
    if process ~= '' then
      label = process .. '|' .. dir
    end
    label = format_fixed(label, TAB_TITLE_LEN)
    return index, label, process, dir
  end

  local palette = {
    { bg = '#007acc', fg = '#ffffff', active_sym = '🚀 🔵  ', inactive_sym = ' ◇' },
    { bg = '#af7ac5', fg = '#ffffff', active_sym = '🚀 🟣  ', inactive_sym = ' ◇' },
    { bg = '#4ec9b0', fg = '#181818', active_sym = '🚀 🟢  ', inactive_sym = ' ◇' },
    { bg = '#ce9178', fg = '#181818', active_sym = '🚀 🔴  ', inactive_sym = ' ◇' },
  }

  wezterm.on('format-tab-title', function(tab, tabs, panes, config, hover, max_width)
    local index, label, process, dir = get_title_info(tab)
    local is_act = tab.is_active
    local c = palette[(tab.tab_index % #palette) + 1]
    if is_act then
      return wezterm.format {
        { Background = { Color = c.bg } },
        { Foreground = { Color = c.fg } },
        { Attribute = { Intensity = 'Bold' } },
        { Attribute = { Underline = 'Single' } },
        { Text = ' ' .. c.active_sym .. index .. ' ' .. label .. ' ✕ ' },
      }
    else
      return wezterm.format {
        { Background = { Color = c.bg } },
        { Foreground = { Color = c.fg } },
        { Text = ' ' .. index .. c.inactive_sym .. ' ' .. label .. ' ✕ ' },
      }
    end
  end)
end

return M